markers = range(3, 13)
for o in markers:
    for c in markers:
        open_line = '"' * o
        close_line = '"' * c
        src = open_line + '\nSENTINEL = 1\n' + close_line + '\nprint("EXEC")\n'
        try:
            code = compile(src, '<x>', 'exec')
        except SyntaxError as e:
            continue
        ns = {}
        import io, contextlib
        out = io.StringIO()
        try:
            with contextlib.redirect_stdout(out):
                exec(code, ns)
        except Exception as e:
            result = 'execerr:' + type(e).__name__
        else:
            result = 'EXEC' if out.getvalue().strip() == 'EXEC' else 'noexec'
        if 'SENTINEL' not in ns:
            state = 'string-skipped'
        else:
            state = 'compiled'
        print(o, c, state, result)
EOF

